test("rejects non-object documents as INVALID_DOCUMENT", () => {
  for (const document of [null, [], "text", 0, false]) {
    assertRejectedAtomically(
      baselineRegistry(),
      document,
      "INVALID_DOCUMENT",
    );
  }
});

test("rejects duplicate ids atomically", () => {
  const cases = [
    {
      name: "schema 2 id already in registry",
      document: {
        schema: 2,
        defaults: {},
        order: ["kept"],
        profiles: {
          kept: {
            label: "Duplicate",
            description: null,
            overrides: {},
          },
        },
      },
    },
    {
      name: "schema 2 repeated order id",
      document: {
        schema: 2,
        defaults: {},
        order: ["a", "a", "b"],
        profiles: {
          a: {
            label: "A",
            description: null,
            overrides: {},
          },
          b: {
            label: "B",
            description: null,
            overrides: {},
          },
        },
      },
    },
    {
      name: "schema 1 id already in registry",
      document: {
        schema: 1,
        defaults: {},
        entries: [["kept", "Duplicate", null, {}]],
      },
    },
    {
      name: "schema 1 repeated id",
      document: {
        schema: 1,
        defaults: {},
        entries: [
          ["a", "A", null, {}],
          ["a", "Again", "", {}],
        ],
      },
    },
  ];

  for (const { name, document } of cases) {
    assert.doesNotThrow(() => {
      assertRejectedAtomically(
        baselineRegistry(),
        document,
        "DUPLICATE_ID",
      );
    }, name);
  }
});
